/* === Inlined wisdom.js === */
/** Rule-based, educational budgeting prompts. No automated external advice or data sharing. */
function moneyGuidance(data,b){
 const result=[];
 const add=(key,tag,kind='general',route=null,icon='✦')=>result.push({title:key+'Title',description:key+'Body',tag,kind,route,icon});
 const monthlySub=(data.subscriptions??[]).filter(s=>s.status==='active').reduce((n,s)=>n+monthly(s.amount,s.period),0);
 const highRate=(data.debts??[]).some(d=>d.balance>0&&d.apr>=15);
 const obligations=(data.debts??[]).filter(d=>d.balance>0).reduce((n,d)=>n+d.minPayment,0);
 const savings=(data.initial??0)-data.goals.reduce((n,g)=>n+g.saved,0);
 if(b.income<=0)add('tipStart','tipPriority','action','budget','1');
 if(b.unallocated<0&&b.income>0)add('tipDeficit','tipPriority','risk','budget','!');
 if(highRate)add('tipInterest','tipPriority','risk','debts','↗');
 else if(obligations>0)add('tipDebt','tipPriority','action','debts','↗');
 if(b.expenses>0&&Math.max(0,savings)<b.expenses*3)add('tipBuffer','tipPriority','action','insights','◉');
 if(monthlySub>0&&(b.income===0||monthlySub>b.income*.07))add('tipSubs','tipReview','action','subscriptions','↻');
 if(data.goals.length&&b.allocated>b.surplus)add('tipGoals','tipPriority','risk','goals','⚑');
 if(b.income>0&&b.unallocated>0)add('tipAuto','tipPlan','action','goals','◷');
 add('tipClear','tipHabit','general','debts','◇');
 add('tipAvoid','tipHabit','general','scenarios','◈');
 add('tipFair','tipHabit','general',null,'♧');
 add('tipSpend','tipHabit','general','insights','◎');
 add('tipGiving','tipHabit','general',null,'♡');
 add('tipProtect','tipHabit','general','future','▤');
 return result;
}

/* === Inlined advanced.js === */
const activeSubscriptions=s=>(s.subscriptions??[]).filter(x=>x.status==='active');
const subscriptionMonthly=s=>sum(activeSubscriptions(s));
const subscriptionYearly=s=>subscriptionMonthly(s)*12;
const debtMinimum=s=>(s.debts??[]).filter(d=>d.balance>0).reduce((n,d)=>n+d.minPayment,0);
const debtMonthly=s=>(s.debts??[]).some(d=>d.balance>0)?debtMinimum(s)+(s.debtExtra??0):0;
const plannedCategories=s=>{
 const map=Object.fromEntries(categoryKeys.map(c=>[c,0]));
 for(const e of s.expenses??[])map[e.category]+=monthly(e.amount,e.period);
 for(const x of activeSubscriptions(s))map[x.category]+=monthly(x.amount,x.period);
 map.debt+=debtMonthly(s);
 return map;
};
function debtPayoff(debts,extra=0,strategy='avalanche',maxMonths=600){
 const active=debts.filter(x=>x.balance>0).map(x=>({...x,remaining:x.balance}));
 const original=active.reduce((n,d)=>n+d.balance,0);
 if(!active.length)return {months:0,interest:0,paid:0,remaining:0,schedule:[],completed:true};
 const payment=active.reduce((n,d)=>n+d.minPayment,0)+extra;
 if(payment<=0)return {months:null,interest:0,paid:0,remaining:original,schedule:[],completed:false};
 let interest=0,paid=0,month=0;
 const schedule=[];
 while(month<maxMonths&&active.some(d=>d.remaining>1e-7)){
  month++;
  const before=active.reduce((n,d)=>n+d.remaining,0);
  for(const d of active){if(d.remaining<=0)continue;const i=d.remaining*d.apr/1200;interest+=i;d.remaining+=i;}
  let left=payment;
  // Minimum payments first. Any freed or unused scheduled minimum is rolled into the target debt.
  for(const d of active){if(d.remaining<=0)continue;const p=Math.min(d.remaining,d.minPayment,left);d.remaining-=p;left-=p;paid+=p;}
  const ordered=active.slice().sort((a,b)=>strategy==='snowball'?a.remaining-b.remaining||b.apr-a.apr:b.apr-a.apr||a.remaining-b.remaining);
  for(const d of ordered){if(left<=0)break;const p=Math.min(d.remaining,left);d.remaining-=p;left-=p;paid+=p;}
  const remaining=active.reduce((n,d)=>n+Math.max(0,d.remaining),0);
  if(month===1||month%12===0||remaining<=1e-7)schedule.push({month,remaining,interest,paid});
  // The debt cannot shrink with this payment (or is growing). Stop promptly.
  if(remaining>=before-1e-7)break;
 }
 const remaining=active.reduce((n,d)=>n+Math.max(0,d.remaining),0);
 const completed=remaining<=1e-6;
 return {months:completed?month:null,interest,paid,remaining,completed,schedule};
}
const emergencyPlan=({expenses,savings,earmarked=0,months=3})=>{
 const usable=Math.max(0,savings-earmarked),target=expenses*months;
 return {usable,target,shortfall:Math.max(0,target-usable),coverage:expenses>0?usable/expenses:null};
};
function spendingAnalysis(s,month){
 const actual=Object.fromEntries(categoryKeys.map(c=>[c,0]));
 for(const entry of s.transactions??[]){if(entry.type==='expense'&&entry.date.startsWith(month))actual[entry.category]+=entry.amount;}
 const planned=plannedCategories(s);
 return categoryKeys.map(category=>({category,planned:planned[category],actual:actual[category],cap:(s.caps??{})[category]??0}));
}

/* === Embedded articles (all four languages) === */
const articleContent={"guide": {"en": "<div class=\"eyebrow\">MY BUDGET · GUIDE<\/div><h1>A clearer plan starts with better questions.<\/h1><p class=\"article-subtitle\">A practical guide to the numbers behind My Budget.<\/p><section class=\"article-section\"><span class=\"article-number\">01<\/span><div><h2>1. Start with money you can actually use<\/h2><p>Enter take-home income after deductions. Add separate sources individually. The planner averages weekly amounts across 52 weeks and divides annual amounts by 12; these monthly averages do not predict the exact dates money arrives.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">02<\/span><div><h2>2. Make occasional costs visible<\/h2><p>A 1,200 annual bill represents a 100 monthly reserve. Keep that reserve separate from discretionary savings. If you also record the actual payment in the journal, it belongs to the actual ledger, not a second planned expense.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">03<\/span><div><h2>3. Assign the surplus only once<\/h2><p>Income minus all planned expenses is the surplus available for goals. If income is 3,000 and expenses total 1,700, the surplus is 1,300. Allocating 500 to one goal leaves 800 for other purposes. Allocating 1,000 to each of two goals exceeds the plan by 700.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">04<\/span><div><h2>4. Turn a wish into a measurable goal<\/h2><p>For a target of 12,000 with 3,000 already saved, 750 per month closes the 9,000 gap in 12 months, assuming no return or withdrawals. A target date makes the required monthly allocation explicit. Completed goals do not automatically spend money or stop contributions: update the plan when your situation changes.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">05<\/span><div><h2>5. Read future projections carefully<\/h2><p>Starting savings plus end-of-month contributions form the baseline. The model converts the effective annual return into a monthly rate. Inflation adjusts future amounts into today’s purchasing power. Constant returns, contributions and inflation are simplifying assumptions, not predictions. Goal purchases, taxes, changing market returns and withdrawals are not included. A negative modeled balance is an unfunded gap.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">06<\/span><div><h2>6. Taxes and international use<\/h2><p>Choose one planning currency and use your own local costs. Currency selection never converts amounts. Enter only a tax reserve that is not already covered by deductions in take-home pay. This site does not determine tax liabilities or official filing dates. For German tax services, consult the official ELSTER portal; My Budget is not affiliated with it.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">07<\/span><div><h2>7. Keep your plan and reality separate<\/h2><p>The budget is a monthly forecast. The journal contains only the actual entries you record for the selected calendar month. Compare them, investigate missing or irregular costs, and revise next month’s plan. Export backups because browser storage is not permanent.<\/p><\/div><\/section><p class=\"source-links\"><a href=\"https://www.elster.de/eportal/start\" rel=\"noopener noreferrer\" target=\"_blank\">ELSTER ↗<\/a><\/p><section class=\"article-section\"><span class=\"article-number\">08<\/span><div><h2>8. Subscriptions, debts and tax documents<\/h2><p>Track active subscriptions and loan payments in their own sections: these automatically reduce available monthly cash, so do not enter the same obligations twice. The debt repayment comparisons assume fixed interest and do not update your balances automatically. In Insights, a cash reserve excludes savings already assigned to goals. The Tax organizer is only a personal checklist: confirm legal filing dates and requirements with official authorities.<\/p><\/div><\/section>", "ar": "<div class=\"eyebrow\">MY BUDGET · GUIDE<\/div><h1>الخطة الواضحة تبدأ بأسئلة أفضل.<\/h1><p class=\"article-subtitle\">دليل عملي للأرقام التي يعتمد عليها My Budget.<\/p><section class=\"article-section\"><span class=\"article-number\">01<\/span><div><h2>1. ابدأ بالمال المتاح فعلًا<\/h2><p>أدخل الدخل الصافي بعد الاقتطاعات، وأضف كل مصدر بشكل مستقل. نحسب المبلغ الأسبوعي وفق 52 أسبوعًا والسنوي مقسومًا على 12. هذا متوسط شهري وليس جدولًا لمواعيد وصول المال.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">02<\/span><div><h2>2. أظهر التكاليف غير الشهرية<\/h2><p>فاتورة سنوية بـ1200 تعني تخصيص 100 شهريًا. افصل هذا الاحتياطي عن الادخار المتاح. وإذا سجلت سداد الفاتورة في السجل الفعلي، فهي عملية فعلية وليست مصروفًا مخططًا ثانيًا.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">03<\/span><div><h2>3. وزّع الفائض مرة واحدة<\/h2><p>الدخل ناقص المصاريف المخططة هو المتاح للأهداف. إذا كان الدخل 3000 والمصاريف 1700، فالفائض 1300. تخصيص 500 لهدف يترك 800. أما تخصيص 1000 لكل هدف من هدفين فيتجاوز المتاح بـ700.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">04<\/span><div><h2>4. حوّل الرغبة إلى هدف قابل للقياس<\/h2><p>هدف بـ12000 ومدخرات مخصصة بـ3000 ومساهمة 750 شهريًا يحتاج 12 شهرًا لسد الفجوة، دون عوائد أو سحوبات. الموعد المستهدف يوضح المساهمة المطلوبة. تحقيق الهدف لا ينفق المال أو يوقف المساهمة تلقائيًا؛ حدّث الخطة عند تغير وضعك.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">05<\/span><div><h2>5. اقرأ المستقبل باعتباره محاكاة<\/h2><p>المدخرات الأولية والمساهمات في نهاية كل شهر هي خط الأساس. نحول العائد السنوي الفعلي إلى معدل شهري ونستخدم التضخم لتقدير القوة الشرائية. ثبات العوائد والتضخم والمساهمات افتراض وليس توقعًا مضمونًا. لا تشمل المحاكاة شراء الأهداف أو الضرائب أو السحوبات. الرصيد السالب يعني فجوة تمويل.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">06<\/span><div><h2>6. الضرائب والاستخدام العالمي<\/h2><p>اختر عملة واحدة وأدخل تكاليفك المحلية. تغيير العملة لا يحوّل الأرقام. أضف فقط ضريبة لم تُحتسب في اقتطاعات الدخل الصافي. لا نحدد التزامات ضريبية أو مواعيد رسمية. للخدمات الضريبية الألمانية راجع ELSTER الرسمي؛ لا توجد علاقة بينه وبين My Budget.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">07<\/span><div><h2>7. افصل الخطة عن الواقع<\/h2><p>الميزانية توقع شهري. السجل يحتوي ما تدخله من عمليات فعلية للشهر المختار فقط. قارنهما وراجع التكاليف الناقصة ثم حدّث خطتك. صدّر نسخًا احتياطية لأن حفظ المتصفح ليس دائمًا.<\/p><\/div><\/section><p class=\"source-links\"><a href=\"https://www.elster.de/eportal/start\" rel=\"noopener noreferrer\" target=\"_blank\">ELSTER ↗<\/a><\/p><section class=\"article-section\"><span class=\"article-number\">08<\/span><div><h2>8. الاشتراكات والديون والوثائق الضريبية<\/h2><p>سجّل الاشتراكات النشطة وأقساط الديون في صفحاتها؛ تُضاف تلقائيًا إلى المصاريف الشهرية، فلا تكررها. محاكاة سداد الديون تفترض فائدة ثابتة ولا تغيّر الرصيد تلقائيًا. يستبعد صندوق الطوارئ الأموال المحجوزة للأهداف. منظم الضرائب قائمة شخصية فقط؛ تحقق من الشروط والآجال من الجهات الرسمية.<\/p><\/div><\/section>", "fr": "<div class=\"eyebrow\">MY BUDGET · GUIDE<\/div><h1>Un plan clair commence par de bonnes questions.<\/h1><p class=\"article-subtitle\">Comprendre les calculs de My Budget.<\/p><section class=\"article-section\"><span class=\"article-number\">01<\/span><div><h2>1. Utilisez le revenu réellement disponible<\/h2><p>Saisissez le revenu net après retenues. Séparez les sources. Les montants hebdomadaires sont annualisés sur 52 semaines, puis divisés par 12. Ces moyennes ne prédisent pas les dates d’encaissement.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">02<\/span><div><h2>2. Prévoyez les dépenses occasionnelles<\/h2><p>Une facture annuelle de 1 200 représente une réserve de 100 par mois. Son paiement réel peut être inscrit au journal, sans créer une deuxième dépense dans le budget prévu.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">03<\/span><div><h2>3. Ne répartissez le surplus qu’une fois<\/h2><p>Avec 3 000 de revenus et 1 700 de dépenses, il reste 1 300. Une allocation de 500 laisse 800. Deux objectifs de 1 000 chacun dépassent la capacité de 700.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">04<\/span><div><h2>4. Rendez chaque objectif mesurable<\/h2><p>Un objectif de 12 000, dont 3 000 déjà réservés, demande 12 mois à 750 par mois, sans rendement ni retrait. Une échéance indique le versement nécessaire. Les achats et arrêts de contribution ne sont pas automatiques : actualisez votre plan.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">05<\/span><div><h2>5. Interprétez les projections<\/h2><p>Le modèle applique un taux mensuel équivalent au rendement annuel et des versements en fin de mois. L’inflation estime le pouvoir d’achat actuel. Les hypothèses constantes ne sont pas des prévisions garanties. Impôts, retraits, achats et variations de marché sont exclus. Un solde négatif est un besoin de financement.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">06<\/span><div><h2>6. Impôts et usage international<\/h2><p>Choisissez une devise et vos propres coûts locaux. Changer de devise ne convertit rien. Ne réservez que les impôts non déjà déduits du revenu net. Le site ne calcule ni dette fiscale ni échéance officielle. Consultez ELSTER pour les services fiscaux allemands ; aucune affiliation.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">07<\/span><div><h2>7. Séparez prévision et réalité<\/h2><p>Le budget est un plan mensuel. Le journal contient seulement vos opérations du mois choisi. Comparez-les et actualisez le plan. Exportez vos données, car le stockage du navigateur peut disparaître.<\/p><\/div><\/section><p class=\"source-links\"><a href=\"https://www.elster.de/eportal/start\" rel=\"noopener noreferrer\" target=\"_blank\">ELSTER ↗<\/a><\/p><section class=\"article-section\"><span class=\"article-number\">08<\/span><div><h2>8. Abonnements, dettes et documents fiscaux<\/h2><p>Les abonnements actifs et paiements de dettes sont déjà pris en compte dans les dépenses mensuelles : évitez les doublons. Les comparaisons de remboursements supposent un taux fixe et ne mettent pas les soldes à jour. La réserve d’urgence exclut les fonds affectés aux objectifs. Le dossier fiscal reste une liste personnelle : vérifiez les échéances officielles.<\/p><\/div><\/section>", "de": "<div class=\"eyebrow\">MY BUDGET · GUIDE<\/div><h1>Ein klarer Plan beginnt mit guten Fragen.<\/h1><p class=\"article-subtitle\">Die Berechnungen hinter My Budget verstehen.<\/p><section class=\"article-section\"><span class=\"article-number\">01<\/span><div><h2>1. Mit verfügbarem Einkommen beginnen<\/h2><p>Erfasse das Nettoeinkommen nach Abzügen und jede Einnahmequelle einzeln. Wochenbeträge werden mit 52 multipliziert und durch 12 geteilt. Diese Monatsdurchschnitte sind kein genauer Zahlungskalender.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">02<\/span><div><h2>2. Unregelmäßige Kosten einplanen<\/h2><p>Eine Jahresrechnung über 1.200 entspricht einer monatlichen Rücklage von 100. Die tatsächliche Zahlung gehört ins Haushaltsbuch, nicht als zweite geplante Ausgabe ins Budget.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">03<\/span><div><h2>3. Den Überschuss nur einmal verteilen<\/h2><p>Bei 3.000 Einnahmen und 1.700 Ausgaben bleiben 1.300. Ein Zielbeitrag von 500 lässt 800 übrig. Je 1.000 für zwei Ziele übersteigt den verfügbaren Betrag um 700.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">04<\/span><div><h2>4. Wünsche messbar machen<\/h2><p>Für ein Ziel von 12.000 mit 3.000 Startguthaben braucht es bei 750 monatlich zwölf Monate, ohne Rendite oder Entnahmen. Ein Zieldatum zeigt den nötigen Beitrag. Zielkäufe und das Beenden von Beiträgen erfolgen nicht automatisch: Aktualisiere den Plan.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">05<\/span><div><h2>5. Prognosen richtig lesen<\/h2><p>Die effektive Jahresrendite wird in einen Monatszins umgerechnet. Beiträge erfolgen am Monatsende, Inflation zeigt heutige Kaufkraft. Konstante Annahmen sind keine Garantie. Steuern, Entnahmen, Zielkäufe und Marktschwankungen sind nicht enthalten. Negative Werte zeigen eine Finanzierungslücke.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">06<\/span><div><h2>6. Steuern und internationale Nutzung<\/h2><p>Wähle eine Planungswährung und nutze eigene lokale Kosten. Ein Währungswechsel rechnet Beträge nicht um. Plane nur Steuern zusätzlich ein, die nicht schon vom Nettoeinkommen abgezogen wurden. Die Anwendung ermittelt weder Steuerschulden noch offizielle Abgabefristen. Für deutsche Steuerdienste nutze das offizielle ELSTER-Portal. My Budget ist nicht mit ELSTER verbunden.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">07<\/span><div><h2>7. Plan und Wirklichkeit trennen<\/h2><p>Das Budget ist ein Monatsplan. Das Haushaltsbuch enthält nur selbst erfasste Buchungen des gewählten Monats. Vergleiche beides und überarbeite den Plan. Exportiere regelmäßig Backups, weil Browserspeicher gelöscht werden kann.<\/p><\/div><\/section><p class=\"source-links\"><a href=\"https://www.elster.de/eportal/start\" rel=\"noopener noreferrer\" target=\"_blank\">ELSTER ↗<\/a><\/p><section class=\"article-section\"><span class=\"article-number\">08<\/span><div><h2>8. Abos, Schulden und Steuerunterlagen<\/h2><p>Aktive Abos und Schuldenraten zählen bereits zu den Monatsausgaben; nicht doppelt erfassen. Tilgungssimulationen rechnen mit festem Zinssatz und ändern keine Schuldsalden. Der Notgroschen berücksichtigt keine schon für Ziele reservierten Beträge. Der Steuerordner ist nur eine persönliche Checkliste: prüfe Fristen und Anforderungen amtlich.<\/p><\/div><\/section>"}, "privacy": {"en": "<div class=\"eyebrow\">MY BUDGET · PRIVACY<\/div><h1>Your financial details belong to you.<\/h1><p class=\"article-subtitle\">Privacy, data handling and use of this version.<\/p><section class=\"article-section\"><span class=\"article-number\">01<\/span><div><h2>Local financial data<\/h2><p>Budget entries, goals, subscriptions, debts, tax-document checklist names/statuses, notes, journal entries and preferences are stored in this browser’s local storage under my-budget-v1. This version has no accounts, bank integrations, server database, analytics or advertising scripts. It does not transmit these financial entries to a backend.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">02<\/span><div><h2>Shared devices and backups<\/h2><p>Local storage is not an encrypted vault. Anyone with access to this browser profile may see your plan. Clearing site data can remove it. JSON backups and CSV exports contain personal information. Store them privately; do not attach them to public support requests.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">03<\/span><div><h2>Hosting and external links<\/h2><p>Your hosting provider may process routine request information, such as an IP address, according to its own policies. Links to external websites open services with their own policies. There are no remote fonts or external script libraries in the planner.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">04<\/span><div><h2>Your controls<\/h2><p>Settings lets you export, restore or delete your financial data. Resetting clears budget records and retains language, currency and theme preferences. Deleting browser site data removes those preferences too. Restore replaces the current plan after confirmation.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">05<\/span><div><h2>Advertising status<\/h2><p>Ads are not active in this version. No publisher account, ad identifier or consent has been assumed. Before enabling advertising, the operator must update this notice, configure the provider’s required consent handling, and keep financial entries out of advertising and analytics requests.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">06<\/span><div><h2>Scope and limitations<\/h2><p>My Budget is a planning and educational tool, not a bank, tax filing service or investment adviser. Inputs, currency units and assumptions are your responsibility. Outputs are estimates and cannot guarantee outcomes. No city cost averages, exchange-rate service or tax calculation is included.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">07<\/span><div><h2>Project support<\/h2><p>Use the linked project repository to report software issues. Never post salary information, tax identifiers, bank details, backups or other private data in a public issue.<\/p><\/div><\/section><p class=\"source-links\"><a href=\"https://github.com/islamtanjawi/My-budget\" rel=\"noopener noreferrer\" target=\"_blank\">GitHub · My Budget ↗<\/a><\/p>", "ar": "<div class=\"eyebrow\">MY BUDGET · PRIVACY<\/div><h1>تفاصيلك المالية تخصك.<\/h1><p class=\"article-subtitle\">الخصوصية ومعالجة البيانات وحدود هذه النسخة.<\/p><section class=\"article-section\"><span class=\"article-number\">01<\/span><div><h2>البيانات المالية المحلية<\/h2><p>تُحفظ الميزانية والأهداف والاشتراكات والديون وقوائم الوثائق الضريبية والملاحظات والعمليات والتفضيلات داخل هذا المتصفح تحت مفتاح my-budget-v1. لا توجد حسابات أو ربط بنكي أو قاعدة بيانات خادمية أو أدوات تحليل أو إعلانات في هذه النسخة، ولا تُرسل المدخلات المالية إلى خادم.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">02<\/span><div><h2>الأجهزة المشتركة والنسخ الاحتياطية<\/h2><p>الحفظ المحلي ليس خزنة مشفرة. من لديه وصول إلى ملف المتصفح قد يرى خطتك. حذف بيانات الموقع قد يمحوها. ملفات JSON وCSV تتضمن معلومات شخصية؛ احفظها بخصوصية ولا ترفقها بطلب دعم علني.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">03<\/span><div><h2>الاستضافة والروابط الخارجية<\/h2><p>قد تعالج جهة الاستضافة معلومات طلب اعتيادية مثل عنوان IP وفق سياستها. الروابط الخارجية تخضع لسياسات خدماتها. لا يحمل المخطط خطوطًا أو مكتبات برمجية من جهات خارجية.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">04<\/span><div><h2>التحكم في بياناتك<\/h2><p>من الإعدادات يمكنك التصدير والاستعادة والحذف. إعادة الضبط تحذف البيانات المالية وتحتفظ باللغة والعملة والمظهر. حذف بيانات الموقع من المتصفح يزيل هذه التفضيلات أيضًا. الاستعادة تستبدل الخطة بعد التأكيد.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">05<\/span><div><h2>حالة الإعلانات<\/h2><p>الإعلانات غير مفعلة في هذه النسخة. لم نفترض حساب ناشر أو معرف إعلاني أو موافقة. قبل تفعيلها يجب تحديث هذه الصفحة وإعداد إدارة الموافقات المطلوبة ومنع إرسال المدخلات المالية للإعلانات والتحليلات.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">06<\/span><div><h2>النطاق والحدود<\/h2><p>My Budget أداة تخطيط وتثقيف وليس بنكًا أو خدمة إقرار ضريبي أو مستشار استثمار. أنت مسؤول عن صحة المدخلات والعملات والافتراضات. النتائج تقديرات وليست ضمانًا. لا تشمل النسخة متوسطات مدن أو تحويل العملات أو حساب الضرائب.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">07<\/span><div><h2>دعم المشروع<\/h2><p>استخدم رابط المستودع للإبلاغ عن الأخطاء البرمجية. لا تنشر الرواتب أو المعرفات الضريبية أو المعلومات البنكية أو النسخ الاحتياطية أو أي بيانات خاصة في بلاغ علني.<\/p><\/div><\/section><p class=\"source-links\"><a href=\"https://github.com/islamtanjawi/My-budget\" rel=\"noopener noreferrer\" target=\"_blank\">GitHub · My Budget ↗<\/a><\/p>", "fr": "<div class=\"eyebrow\">MY BUDGET · PRIVACY<\/div><h1>Vos informations financières vous appartiennent.<\/h1><p class=\"article-subtitle\">Confidentialité et limites de cette version.<\/p><section class=\"article-section\"><span class=\"article-number\">01<\/span><div><h2>Données locales<\/h2><p>Budgets, objectifs, abonnements, dettes, liste des pièces fiscales, notes, opérations et préférences sont stockés dans ce navigateur sous my-budget-v1. Aucun compte, connexion bancaire, base serveur, outil analytique ou script publicitaire. Les données financières ne sont pas transmises à un serveur applicatif.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">02<\/span><div><h2>Appareils partagés et sauvegardes<\/h2><p>Le stockage local n’est pas un coffre chiffré. Une personne ayant accès au profil du navigateur peut consulter les données. Les exports JSON et CSV contiennent des informations personnelles : gardez-les privés.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">03<\/span><div><h2>Hébergement et liens externes<\/h2><p>L’hébergeur peut traiter des informations techniques telles qu’une adresse IP selon sa politique. Les liens externes ont leurs propres règles. Aucun chargement de polices ou bibliothèques externes.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">04<\/span><div><h2>Vos contrôles<\/h2><p>Exportez, restaurez ou supprimez vos données dans les réglages. La réinitialisation conserve langue, devise et thème ; effacer les données du site les supprime aussi. La restauration remplace le plan après confirmation.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">05<\/span><div><h2>Publicité<\/h2><p>Aucune publicité active. Aucun compte éditeur ou consentement n’est présumé. Avant activation, l’exploitant doit actualiser cette notice et gérer les consentements requis. Les données financières ne doivent pas être envoyées aux services publicitaires.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">06<\/span><div><h2>Limites<\/h2><p>Outil de planification et d’éducation, pas une banque, un service de déclaration fiscale ou un conseiller en placement. Les résultats sont estimatifs. Pas de moyennes de coûts par ville, de conversion monétaire ni de calcul fiscal.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">07<\/span><div><h2>Assistance<\/h2><p>Signalez les problèmes logiciels dans le dépôt du projet. Ne publiez pas de salaire, identifiant fiscal, coordonnées bancaires ou sauvegardes dans une demande publique.<\/p><\/div><\/section><p class=\"source-links\"><a href=\"https://github.com/islamtanjawi/My-budget\" rel=\"noopener noreferrer\" target=\"_blank\">GitHub · My Budget ↗<\/a><\/p>", "de": "<div class=\"eyebrow\">MY BUDGET · PRIVACY<\/div><h1>Deine Finanzdaten gehören dir.<\/h1><p class=\"article-subtitle\">Datenschutz, Datenverarbeitung und Grenzen dieser Version.<\/p><section class=\"article-section\"><span class=\"article-number\">01<\/span><div><h2>Lokale Daten<\/h2><p>Budget, Ziele, Notizen, Buchungen und Einstellungen werden im lokalen Speicher dieses Browsers unter my-budget-v1 gespeichert. Keine Konten, Bankanbindung, Serverdatenbank, Analyse- oder Werbeskripte. Finanzielle Eingaben werden nicht an ein Anwendungsbackend gesendet.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">02<\/span><div><h2>Gemeinsame Geräte und Backups<\/h2><p>Lokaler Speicher ist kein verschlüsselter Tresor. Personen mit Zugriff auf das Browserprofil können deinen Plan einsehen. JSON-Backups und CSV-Dateien enthalten persönliche Informationen. Bewahre sie privat auf.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">03<\/span><div><h2>Hosting und externe Links<\/h2><p>Der Hostinganbieter kann technische Anfragedaten wie IP-Adressen nach seinen Richtlinien verarbeiten. Externe Links unterliegen eigenen Richtlinien. Keine externen Schriftarten oder Skriptbibliotheken werden geladen.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">04<\/span><div><h2>Deine Kontrolle<\/h2><p>In den Einstellungen kannst du exportieren, wiederherstellen und löschen. Zurücksetzen behält Sprache, Währung und Farbschema bei. Das Löschen der Website-Daten im Browser entfernt auch diese Einstellungen. Wiederherstellung ersetzt nach Bestätigung den aktuellen Plan.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">05<\/span><div><h2>Werbung<\/h2><p>Werbung ist nicht aktiviert. Weder ein Werbekonto noch eine Einwilligung wird vorausgesetzt. Vor Aktivierung muss der Betreiber diese Hinweise und erforderliche Einwilligungsverwaltung ergänzen. Finanzdaten dürfen nicht an Werbe- oder Analysedienste gesendet werden.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">06<\/span><div><h2>Grenzen<\/h2><p>Ein Planungs- und Lernwerkzeug, keine Bank, Steuererklärungssoftware oder Anlageberatung. Ergebnisse sind Schätzungen. Keine örtlichen Kostendurchschnitte, Wechselkurse oder Steuerberechnungen enthalten.<\/p><\/div><\/section><section class=\"article-section\"><span class=\"article-number\">07<\/span><div><h2>Projekt-Support<\/h2><p>Melde Softwareprobleme im Projekt-Repository. Veröffentliche keine Gehaltsangaben, Steueridentifikationsnummern, Bankdaten oder Backups in öffentlichen Meldungen.<\/p><\/div><\/section><p class=\"source-links\"><a href=\"https://github.com/islamtanjawi/My-budget\" rel=\"noopener noreferrer\" target=\"_blank\">GitHub · My Budget ↗<\/a><\/p>"}};
